    ax.set_title('Review Length vs Sentiment Polarity', fontsize=14, fontweight='bold')
    ax.axhline(y=0, color='black', linestyle='--', alpha=0.3)
    ax.legend(loc='upper right')
    ax.set_xlim(0, 300)
    ax.set_ylim(-1.1, 1.1)

    plt.tight_layout()
    return create_chart_base64(fig)

