#!/usr/bin/env python3
"""
Generative AI Competitive Landscape Analysis Report Generator
Analyzes 50,000 user reviews across 5 AI apps and generates an HTML report.
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib
matplotlib.use('Agg')
import json
from pathlib import Path
from io import BytesIO
import base64

# File paths
DATA_PATH = '/app/benchmark/data.csv'
OUTPUT_PATH = '/app/output/final_report.html'

# App names (handle BOM)
APPS = ['ChatGPT', 'Microsoft Copilot', 'Google Gemini', 'Perplexity', 'Claude']

# Colors for each app
APP_COLORS = {
    'ChatGPT': '#10a37f',
    'Microsoft Copilot': '#0078d4',
    'Google Gemini': '#4285f4',
    'Perplexity': '#54a4ff',
    'Claude': '#d4a574'
}

def load_data():
    """Load and preprocess the dataset."""
    df = pd.read_csv(DATA_PATH, encoding='utf-8-sig')
    df.columns = df.columns.str.replace('\ufeff', '')  # Remove BOM
    return df

def compute_kpis(df):
    """Compute all required KPIs."""
    kpis = {}

    # 1. Average Star Rating by App
    kpis['avg_star_rating'] = df.groupby('App')['Star_Rating'].mean().round(3).to_dict()

    # 2. Mean Sentiment Polarity by App
    kpis['avg_sentiment'] = df.groupby('App')['Sentiment_Polarity'].mean().round(3).to_dict()

    # 3. Complaint Theme Rate (Pricing, Bugs, Accuracy vs General)
    theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
    total_per_app = theme_counts.sum(axis=1)

    # Map themes to categories
    theme_mapping = {
        'Pricing/Subscription': 'Pricing',
        'Bugs/Performance': 'Bugs',
        'Accuracy/Logic Issues': 'Accuracy',
        'General': 'General'
    }

    complaint_rate = {}
    for app in APPS:
        app_data = df[df['App'] == app]
        total = len(app_data)
        complaints = len(app_data[app_data['Review_Theme'] != 'General'])
        complaint_rate[app] = round((complaints / total) * 100, 1) if total > 0 else 0

        # Specific theme rates
        for theme in ['Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']:
            theme_key = theme_mapping[theme]
            count = len(app_data[app_data['Review_Theme'] == theme])
            if f'{theme_key}_rate' not in kpis:
                kpis[f'{theme_key}_rate'] = {}
            kpis[f'{theme_key}_rate'][app] = round((count / total) * 100, 1) if total > 0 else 0

    kpis['complaint_rate'] = complaint_rate

    # 4. Sentiment-Rating Mismatch Rate
    # Define mismatch: 5-star with negative sentiment (<-0.3), or 1-star with positive sentiment (>0.3)
    mismatch_rates = {}
    for app in APPS:
        app_data = df[df['App'] == app]
        total = len(app_data)

        # High rating (4-5) but negative sentiment
        high_neg = len(app_data[(app_data['Star_Rating'] >= 4) & (app_data['Sentiment_Polarity'] < -0.3)])
        # Low rating (1-2) but positive sentiment
        low_pos = len(app_data[(app_data['Star_Rating'] <= 2) & (app_data['Sentiment_Polarity'] > 0.3)])

        mismatch_count = high_neg + low_pos
        mismatch_rates[app] = round((mismatch_count / total) * 100, 1) if total > 0 else 0

    kpis['mismatch_rate'] = mismatch_rates

    # 5. Average Review Engagement (Thumbs Up)
    kpis['avg_thumbs_up'] = df.groupby('App')['Thumbs_Up_Count'].mean().round(2).to_dict()

    # Thumbs up by theme
    thumbs_by_theme = {}
    for app in APPS:
        thumbs_by_theme[app] = {}
        for theme in ['General', 'Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']:
            theme_data = df[(df['App'] == app) & (df['Review_Theme'] == theme)]
            thumbs_by_theme[app][theme] = round(theme_data['Thumbs_Up_Count'].mean(), 2) if len(theme_data) > 0 else 0

    kpis['thumbs_by_theme'] = thumbs_by_theme

    # Review counts
    kpis['review_counts'] = df.groupby('App').size().to_dict()

    return kpis

def create_chart_base64(fig):
    """Convert matplotlib figure to base64."""
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

def create_star_rating_chart(kpis):
    """Create star rating comparison chart."""
    apps = APPS
    ratings = [kpis['avg_star_rating'][app] for app in apps]
    colors = [APP_COLORS[app] for app in apps]

    fig, ax = plt.subplots(figsize=(8, 5))
    bars = ax.bar(apps, ratings, color=colors, edgecolor='white', linewidth=1.5)

    # Add value labels
    for bar, val in zip(bars, ratings):
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.05,
                f'{val:.2f}', ha='center', va='bottom', fontsize=11, fontweight='bold')

    ax.set_ylim(0, 5.5)
    ax.set_ylabel('Average Star Rating', fontsize=11)
    ax.set_title('Average Star Rating by Application', fontsize=14, fontweight='bold')
    ax.axhline(y=4.0, color='gray', linestyle='--', alpha=0.5, label='Good threshold')

    plt.xticks(rotation=15, ha='right')
    plt.tight_layout()

    return create_chart_base64(fig)

def create_sentiment_chart(kpis):
    """Create sentiment polarity comparison chart."""
    apps = APPS
    sentiments = [kpis['avg_sentiment'][app] for app in apps]
    colors = [APP_COLORS[app] for app in apps]

    fig, ax = plt.subplots(figsize=(8, 5))
    bars = ax.bar(apps, sentiments, color=colors, edgecolor='white', linewidth=1.5)

    for bar, val in zip(bars, sentiments):
        color = 'green' if val >= 0 else 'red'
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.02,
                f'{val:.3f}', ha='center', va='bottom', fontsize=10, fontweight='bold')

    ax.set_ylim(-0.5, 0.8)
    ax.set_ylabel('Mean VADER Sentiment Polarity', fontsize=11)
    ax.set_title('Mean Sentiment Polarity by Application', fontsize=14, fontweight='bold')
    ax.axhline(y=0, color='black', linestyle='-', alpha=0.3)

    plt.xticks(rotation=15, ha='right')
    plt.tight_layout()

    return create_chart_base64(fig)

def create_theme_breakdown_chart(df):
    """Create thematic complaint breakdown chart."""
    theme_mapping = {
        'Pricing/Subscription': 'Pricing',
        'Bugs/Performance': 'Bugs',
        'Accuracy/Logic Issues': 'Accuracy',
        'General': 'General'
    }

    apps = APPS
    themes = ['Pricing', 'Bugs', 'Accuracy', 'General']
    theme_colors = {'Pricing': '#e74c3c', 'Bugs': '#f39c12', 'Accuracy': '#9b59b6', 'General': '#3498db'}

    data = {theme: [] for theme in themes}

    for app in apps:
        app_data = df[df['App'] == app]
        total = len(app_data)
        for theme in themes:
            if theme == 'General':
                count = len(app_data[app_data['Review_Theme'] == 'General'])
            elif theme == 'Pricing':
                count = len(app_data[app_data['Review_Theme'] == 'Pricing/Subscription'])
            elif theme == 'Bugs':
                count = len(app_data[app_data['Review_Theme'] == 'Bugs/Performance'])
            elif theme == 'Accuracy':
                count = len(app_data[app_data['Review_Theme'] == 'Accuracy/Logic Issues'])
            data[theme].append(round((count / total) * 100, 1) if total > 0 else 0)

    x = np.arange(len(apps))
    width = 0.2

    fig, ax = plt.subplots(figsize=(10, 6))
    for i, theme in enumerate(themes):
        offset = (i - 1.5) * width
        bars = ax.bar(x + offset, data[theme], width, label=theme, color=theme_colors[theme])

    ax.set_ylabel('% of Reviews', fontsize=11)
    ax.set_xlabel('Application', fontsize=11)
    ax.set_title('Review Theme Distribution by Application', fontsize=14, fontweight='bold')
    ax.set_xticks(x)
    ax.set_xticklabels(apps, rotation=15, ha='right')
    ax.legend(title='Theme', loc='upper right')
    ax.set_ylim(0, 100)

    plt.tight_layout()
    return create_chart_base64(fig)

def create_mismatch_chart(kpis):
    """Create sentiment-rating mismatch chart."""
    apps = APPS
    mismatch = [kpis['mismatch_rate'][app] for app in apps]
    colors = [APP_COLORS[app] for app in apps]

    fig, ax = plt.subplots(figsize=(8, 5))
    bars = ax.bar(apps, mismatch, color=colors, edgecolor='white', linewidth=1.5)

    for bar, val in zip(bars, mismatch):
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.2,
                f'{val}%', ha='center', va='bottom', fontsize=11, fontweight='bold')

    ax.set_ylim(0, max(mismatch) * 1.2 + 2)
    ax.set_ylabel('Mismatch Rate (%)', fontsize=11)
    ax.set_title('Sentiment-Rating Mismatch Rate by Application', fontsize=14, fontweight='bold')

    plt.xticks(rotation=15, ha='right')
    plt.tight_layout()

    return create_chart_base64(fig)

def create_rating_distribution_chart(df):
    """Create star rating distribution chart."""
    apps = APPS

    fig, axes = plt.subplots(2, 3, figsize=(14, 8))
    axes = axes.flatten()

    for idx, app in enumerate(apps):
        app_data = df[df['App'] == app]
        rating_counts = app_data['Star_Rating'].value_counts().sort_index()

        colors_ratings = ['#e74c3c', '#f39c12', '#f1c40f', '#27ae60', '#27ae60']
        bars = axes[idx].bar(rating_counts.index, rating_counts.values, color=colors_ratings)
        axes[idx].set_title(f'{app}', fontsize=12, fontweight='bold')
        axes[idx].set_xlabel('Star Rating')
        axes[idx].set_ylabel('Count')
        axes[idx].set_xticks([1, 2, 3, 4, 5])

    # Hide the 6th subplot
    axes[5].axis('off')

    plt.suptitle('Star Rating Distribution by Application', fontsize=16, fontweight='bold', y=1.02)
    plt.tight_layout()

    return create_chart_base64(fig)

def create_word_count_sentiment_scatter(df):
    """Create scatter plot of word count vs sentiment."""
    fig, ax = plt.subplots(figsize=(10, 6))

    # Sample for visibility
    sample = df.sample(min(5000, len(df)), random_state=42)

    for app in APPS:
