    ax.legend(loc='upper right')
    ax.set_xlim(0, 300)
    ax.set_ylim(-1.1, 1.1)

    plt.tight_layout()
    return create_chart_base64(fig)

def create_thumbs_up_chart(kpis):
    """Create average thumbs up by theme chart."""
    themes = ['General', 'Pricing', 'Bugs', 'Accuracy']
    theme_colors = {'General': '#3498db', 'Pricing': '#e74c3c', 'Bugs': '#f39c12', 'Accuracy': '#9b59b6'}

    apps = APPS
