        .insight-box.success {{ background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%); border-left-color: var(--success); }}

        .key-takeaways {{ display: grid; gap: 15px; }}

        .takeaway {{
            display: flex;
            gap: 15px;
            align-items: flex-start;
            padding: 15px;
            background: #f8fafc;
            border-radius: 8px;
