        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }}

        .kpi-card {{
            background: linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%);
