    apps = APPS
    labels = [APP_DISPLAY[a] for a in apps]
    themes = ['General', 'Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']
    theme_names = ['General', 'Pricing', 'Bugs', 'Accuracy']
    theme_colors = ['#3498db', '#e74c3c', '#f39c12', '#9b59b6']

    x = np.arange(len(labels))
    width = 0.2

    fig, ax = plt.subplots(figsize=(10, 6))
    for i, (theme_name, color) in enumerate(zip(theme_names, theme_colors)):
        offset = (i - 1.5) * width
        values = [kpis['thumbs_by_theme'][app].get(theme, 0) for app in apps]
        bars = ax.bar(x + offset, values, width, label=theme_name, color=color)

    ax.set_ylabel('Average Thumbs Up', fontsize=11)
    ax.set_xlabel('Application', fontsize=11)
    ax.set_title('Review Engagement (Thumbs Up) by Theme', fontsize=14, fontweight='bold')
    ax.set_xticks(x)
    ax.set_xticklabels(labels, rotation=15, ha='right')
    ax.legend(title='Theme', loc='upper right')

    plt.tight_layout()
    return create_chart_base64(fig)

